INSERT INTO dogs(id,name,breed,sex,age,status,description,photos,health) VALUES('marleigh','Marleigh','Great Dane mix','Female','2 years old (turns 3 in November)','available','Marleigh came to Salty Dog last May frightened and underweight after being abandoned. Today, she is healthy, happy and eager to make friends. She loves people, gets along well with the other shelter dogs and enjoys long leash walks, forest outings and running alongside a bicycle.

Because she is large, strong and sometimes overly excited by bicycles, skateboards, deer and unfamiliar dogs, Marleigh would thrive in a calm home with someone experienced with strong dogs who can provide structure and continue working with her. She also rides wonderfully in the car.','["/assets/dogs/marleigh/photos/marleigh1.jpg","/assets/dogs/marleigh/photos/marleigh2.jpg","/assets/dogs/marleigh/photos/marleigh3.jpg","/assets/dogs/marleigh/photos/marleigh4.jpg","/assets/dogs/marleigh/photos/marleigh5.jpg","/assets/dogs/marleigh/photos/marleigh6.jpg"]','["Spayed","Vaccinations current","Microchipped","House-trained"]') ON CONFLICT(id) DO NOTHING;
INSERT INTO dogs(id,name,breed,sex,age,status,description,photos,health) VALUES('wiggles','Wiggles','Staffordshire mix','Female','1 year old','available','Wiggles is a sweet, people-loving puppy who is also friendly with other dogs. When playtime starts, she brings the enthusiasm and loves a good rough-and-tumble session. She is spayed, current on her vaccinations and ready to meet the family who will love her energy and affectionate nature.','["/assets/dogs/wiggles/photos/wiggles-3.webp","/assets/dogs/wiggles/photos/wiggles-1.webp","/assets/dogs/wiggles/photos/wiggles-2.webp","/assets/dogs/wiggles/photos/wiggles-4.webp"]','["Spayed","Vaccinations current","Dog friendly"]') ON CONFLICT(id) DO NOTHING;
